package de.ungarnet.stonechests;

import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.inventory.ItemStack;
import java.io.File; import java.sql.*; import java.util.*;

final class Database implements AutoCloseable {
  private final Connection c;
  Database(File file) throws SQLException { c=DriverManager.getConnection("jdbc:sqlite:"+file.getAbsolutePath()); migrate(); }
  private void migrate() throws SQLException { try(Statement s=c.createStatement()) { s.executeUpdate("CREATE TABLE IF NOT EXISTS sc_meta (version INTEGER NOT NULL)"); try(ResultSet r=s.executeQuery("SELECT count(*) FROM sc_meta")){if(r.next()&&r.getInt(1)==0)s.executeUpdate("INSERT INTO sc_meta VALUES(1)");} s.executeUpdate("CREATE TABLE IF NOT EXISTS sc_chests (id TEXT PRIMARY KEY,type TEXT NOT NULL,world TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,hologram TEXT,pages INTEGER NOT NULL DEFAULT 3)"); try{s.executeUpdate("ALTER TABLE sc_chests ADD COLUMN pages INTEGER NOT NULL DEFAULT 3");}catch(SQLException ignored){} s.executeUpdate("CREATE TABLE IF NOT EXISTS sc_items (chest_id TEXT NOT NULL,page INTEGER NOT NULL,slot INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(chest_id,page,slot),FOREIGN KEY(chest_id) REFERENCES sc_chests(id) ON DELETE CASCADE)"); s.executeUpdate("CREATE INDEX IF NOT EXISTS sc_location ON sc_chests(world,x,y,z)"); } }
  synchronized List<StoredChest> load() throws SQLException { Map<UUID,StoredChest> all=new HashMap<>(); try(PreparedStatement q=c.prepareStatement("SELECT * FROM sc_chests"); ResultSet r=q.executeQuery()){while(r.next()){ UUID id=UUID.fromString(r.getString("id")); var world=Bukkit.getWorld(UUID.fromString(r.getString("world"))); if(world==null)continue; ChestType type=ChestType.valueOf(r.getString("type")); StoredChest x=new StoredChest(id,type,new Location(world,r.getInt("x"),r.getInt("y"),r.getInt("z")),Math.max(type.defaultPages,r.getInt("pages"))); String h=r.getString("hologram"); if(h!=null)x.hologram=UUID.fromString(h); all.put(id,x); }} try(PreparedStatement q=c.prepareStatement("SELECT * FROM sc_items"); ResultSet r=q.executeQuery()){while(r.next()){StoredChest x=all.get(UUID.fromString(r.getString("chest_id")));if(x!=null&&r.getInt("page")<x.pages.length)x.pages[r.getInt("page")][r.getInt("slot")]=ItemStack.deserializeBytes(r.getBytes("data"));}} return new ArrayList<>(all.values()); }
  synchronized void save(StoredChest x) throws SQLException { c.setAutoCommit(false); try { try(PreparedStatement q=c.prepareStatement("INSERT OR REPLACE INTO sc_chests(id,type,world,x,y,z,hologram,pages) VALUES(?,?,?,?,?,?,?,?)")){q.setString(1,x.id.toString());q.setString(2,x.type.name());q.setString(3,x.location.getWorld().getUID().toString());q.setInt(4,x.location.getBlockX());q.setInt(5,x.location.getBlockY());q.setInt(6,x.location.getBlockZ());q.setString(7,x.hologram==null?null:x.hologram.toString());q.setInt(8,x.pages.length);q.executeUpdate();} try(PreparedStatement q=c.prepareStatement("DELETE FROM sc_items WHERE chest_id=?")){q.setString(1,x.id.toString());q.executeUpdate();} try(PreparedStatement q=c.prepareStatement("INSERT INTO sc_items VALUES(?,?,?,?)")){ for(int p=0;p<x.pages.length;p++)for(int s=0;s<54;s++)if(x.pages[p][s]!=null&&!x.pages[p][s].getType().isAir()){q.setString(1,x.id.toString());q.setInt(2,p);q.setInt(3,s);q.setBytes(4,x.pages[p][s].serializeAsBytes());q.addBatch();}q.executeBatch();} c.commit(); } catch(SQLException e){c.rollback();throw e;} finally {c.setAutoCommit(true);} }
  synchronized void delete(UUID id) throws SQLException {try(PreparedStatement q=c.prepareStatement("DELETE FROM sc_chests WHERE id=?")){q.setString(1,id.toString());q.executeUpdate();}}
  public void close() throws SQLException {c.close();}
}
